select id, user_id, order_id, product_id, content, star, create_time, update_time
from comment
where id = #{id}

select id, user_id, order_id, product_id, content, star, create_time, update_time
from comment


        and user_id = #{userId}


        and order_id = #{orderId}


        and product_id = #{productId}


        and content like concat('%', #{content}, '%')


        and star = #{star}


order by create_time desc

select id, user_id, order_id, product_id, content, star, create_time, update_time from comment where id in
#{id}
order by create_time desc

select id, user_id, order_id, product_id, content, star, create_time, update_time
from comment
where product_id = #{productId}
and star = #{star}
order by create_time desc

select coalesce(avg(star), 0.0)
from comment
where product_id = #{productId}

select count(*)
from comment
where product_id = #{productId}

select id, user_id, order_id, product_id, content, star, create_time, update_time
from comment
where user_id = #{userId}
and order_id = #{orderId}
and product_id = #{productId}
limit 1

select id, user_id, order_id, product_id, content, star, create_time, update_time
from comment
where product_id = #{productId}
order by create_time desc
limit #{offset}, #{limit}
